@import "tailwindcss";

/*
 * Carhop Marquee / Gulf Channel design system.
 * Five named colors only, see design-system.md. No pure black/white anywhere.
 */
@theme inline {
  --color-bay-dusk: #0e3a3e;
  --color-channel-ink: #082226;
  --color-marquee-amber: #e8a23c;
  --color-seafoam: #ecefe6;
  --color-buoy-red: #d1452b;

  --font-display: var(--font-roboto-slab);
  --font-body: var(--font-archivo);
  --font-mono: var(--font-plex-mono);
}

@custom-variant reduced-motion (&:where([data-reduced-motion="true"] *, [data-reduced-motion="true"]));

html {
  color-scheme: dark;
}

body {
  background: var(--color-bay-dusk);
  color: var(--color-seafoam);
  font-family: var(--font-body), sans-serif;
}

/* Respect prefers-reduced-motion globally: collapse any transform/opacity transition or animation. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

