@import "tailwindcss";

/*
 * Carhop Marquee / Gulf Channel design system (design-system.md).
 * Five named colors only. No pure black/white anywhere.
 * These CSS variables are consumed both by our own utility classes
 * (bg-bay-dusk, text-marquee-amber, etc.) and by the shadcn Button
 * primitive's existing variant classes (bg-primary, bg-background, ring-ring),
 * so the button is restyled through the design tokens rather than left
 * on shadcn's neutral defaults.
 */
@theme inline {
  --color-bay-dusk: var(--bay-dusk);
  --color-channel-ink: var(--channel-ink);
  --color-marquee-amber: var(--marquee-amber);
  --color-seafoam: var(--seafoam);
  --color-buoy-red: var(--buoy-red);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --font-display: var(--font-roboto-slab);
  --font-body: var(--font-archivo);
  --font-mono: var(--font-plex-mono);

  --radius-sm: 4px;
  --radius-md: 4px;
  --radius-lg: 4px;
}

:root {
  --bay-dusk: #0e3a3e;
  --channel-ink: #082226;
  --marquee-amber: #e8a23c;
  --seafoam: #ecefe6;
  --buoy-red: #d1452b;

  --background: var(--bay-dusk);
  --foreground: var(--seafoam);
  --primary: var(--marquee-amber);
  --primary-foreground: var(--channel-ink);
  --secondary: var(--channel-ink);
  --secondary-foreground: var(--seafoam);
  --muted: #ecefe61a;
  --muted-foreground: #ecefe6cc;
  --accent: #ecefe61a;
  --accent-foreground: var(--seafoam);
  --destructive: #d1452b;
  --border: #ecefe633;
  --input: #ecefe61a;
  --ring: var(--marquee-amber);
}

html {
  color-scheme: dark;
}

body {
  font-family: var(--font-body), sans-serif;
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Respect prefers-reduced-motion globally: collapse any transition/animation. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

