"use client";

import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

// The site's signature component (design-system.md): "THE TEXAN DRIVE-IN" as
// individually backlit porcelain-marquee letter tiles. On first hero load
// only, it flickers on like a real sign powering up, then settles steady-lit
// and never repeats within the session (tracked via sessionStorage). Every
// other usage (nav, footer) renders the same tiles already steady-lit, no
// animation, per implementation.md's "only one with the flicker-on" rule.

const WORDS = ["THE", "TEXAN", "DRIVE-IN"];
const SESSION_KEY = "texan-marquee-lit";

const TILE_SIZE = {
  hero: "text-2xl sm:text-3xl md:text-4xl w-[1.2em] h-[1.35em]",
  compact: "text-xs sm:text-sm w-[1.3em] h-[1.5em]",
} as const;

const GLYPH_SIZE = {
  hero: "text-2xl sm:text-3xl md:text-4xl px-0.5",
  compact: "text-xs sm:text-sm px-0.5",
} as const;

export function MarqueeWordmark({
  size = "hero",
  className = "",
}: {
  size?: "hero" | "compact";
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  const [shouldAnimate, setShouldAnimate] = useState(false);

  useEffect(() => {
    if (size !== "hero" || reduceMotion) return;
    if (typeof window === "undefined") return;
    if (window.sessionStorage.getItem(SESSION_KEY)) return;
    window.sessionStorage.setItem(SESSION_KEY, "1");
    setShouldAnimate(true);
  }, [size, reduceMotion]);

  let tileIndex = 0;

  return (
    <div
      className={`flex flex-wrap items-center gap-x-2 gap-y-1 ${className}`}
      role="img"
      aria-label={`${WORDS.join(" ")}`}
    >
      {WORDS.map((word, wordIdx) => (
        <div key={wordIdx} className="flex" aria-hidden="true">
          {[...word].map((char, charIdx) => {
            if (char === "-") {
              return (
                <span
                  key={charIdx}
                  className={`flex items-center justify-center font-display font-black text-marquee-amber ${GLYPH_SIZE[size]}`}
                >
                  {char}
                </span>
              );
            }
            const i = tileIndex++;
            return (
              <motion.span
                key={charIdx}
                initial={shouldAnimate ? { opacity: 0.15 } : false}
                animate={
                  shouldAnimate
                    ? { opacity: [0.15, 1, 0.2, 1, 0.25, 1] }
                    : { opacity: 1 }
                }
                transition={
                  shouldAnimate
                    ? {
                        duration: 0.6,
                        delay: i * 0.02,
                        times: [0, 0.2, 0.4, 0.6, 0.8, 1],
                        ease: "easeOut",
                      }
                    : { duration: 0 }
                }
                className={`flex items-center justify-center border border-marquee-amber/25 bg-channel-ink font-display font-black leading-none text-marquee-amber ${TILE_SIZE[size]}`}
              >
                {char}
              </motion.span>
            );
          })}
        </div>
      ))}
    </div>
  );
}

