"use client";

import Link from "next/link";
import { useState } from "react";
import { useMotionValueEvent, useScroll } from "motion/react";
import { List, X } from "@phosphor-icons/react";
import { MarqueeWordmark } from "./MarqueeWordmark";
import { NAV_LINKS } from "@/lib/site";

// Sticky, one line, max 72px tall (page-plans/home.md). Transparent over the
// hero, solid Channel Ink once scrolled past it, tracked via Motion's
// useScroll rather than a raw scroll listener. No CTA in the nav: the hero
// carries both CTAs already (no-duplicate-CTA-intent rule).
export function NavBar() {
  const { scrollY } = useScroll();
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useMotionValueEvent(scrollY, "change", (latest) => {
    setScrolled(latest > 48);
  });

  return (
    <header
      className={`sticky top-0 z-40 border-b transition-colors duration-300 ${
        scrolled
          ? "border-seafoam/10 bg-channel-ink/95 backdrop-blur-sm"
          : "border-transparent bg-transparent"
      }`}
    >
      <nav className="mx-auto flex h-16 max-w-6xl items-center justify-between px-4 md:h-[72px] md:px-8">
        <Link href="/" aria-label="The Texan Drive-In, home" className="shrink-0">
          <MarqueeWordmark size="compact" />
        </Link>

        <ul className="hidden items-center gap-8 md:flex">
          {NAV_LINKS.map((link) => (
            <li key={link.href}>
              <Link
                href={link.href}
                className="font-body text-sm font-medium text-seafoam/90 transition-colors hover:text-marquee-amber"
              >
                {link.label}
              </Link>
            </li>
          ))}
        </ul>

        <button
          type="button"
          onClick={() => setMenuOpen((open) => !open)}
          aria-expanded={menuOpen}
          aria-label={menuOpen ? "Close menu" : "Open menu"}
          className="flex size-11 items-center justify-center text-seafoam md:hidden"
        >
          {menuOpen ? <X size={24} /> : <List size={24} />}
        </button>
      </nav>

      {menuOpen && (
        <ul className="flex flex-col gap-1 border-t border-seafoam/10 bg-channel-ink px-4 pb-4 md:hidden">
          {NAV_LINKS.map((link) => (
            <li key={link.href}>
              <Link
                href={link.href}
                onClick={() => setMenuOpen(false)}
                className="flex h-11 items-center font-body text-base font-medium text-seafoam/90 hover:text-marquee-amber"
              >
                {link.label}
              </Link>
            </li>
          ))}
        </ul>
      )}
    </header>
  );
}

