"use client";

import type { ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";

// Shared scroll-reveal per design-system.md: one clean fade-and-rise pass on
// section entry, no restart on re-scroll, collapses to instantly-visible
// under prefers-reduced-motion. Used below the hero only; the hero itself
// must be visible without any scroll-gated transition.
export function Reveal({
  children,
  className = "",
  delay = 0,
}: {
  children: ReactNode;
  className?: string;
  delay?: number;
}) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduceMotion ? false : { opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.3 }}
      transition={{ duration: 0.6, delay, ease: [0.16, 1, 0.3, 1] }}
    >
      {children}
    </motion.div>
  );
}

