import { SCHEDULE, type ScheduleRow } from "@/lib/schedule";
import { Reveal } from "./Reveal";

// The site's signature component doing real scheduling work, reused as a
// small teaser on the homepage and at full size on /whats-on (design-system.md,
// handling-protocols.md's token-cost note: one widget, not two).
export function MarqueeBoard({ variant = "full" }: { variant?: "teaser" | "full" }) {
  const rows = variant === "teaser" ? SCHEDULE.slice(0, 1) : SCHEDULE;
  return (
    <Reveal className="mx-auto max-w-4xl px-4 md:px-8">
      <div className="divide-y divide-marquee-amber/20 border border-marquee-amber/20 bg-channel-ink">
        {rows.map((row) => (
          <MarqueeRow key={row.day} row={row} />
        ))}
      </div>
    </Reveal>
  );
}

function MarqueeRow({ row }: { row: ScheduleRow }) {
  return (
    <div className="flex flex-col gap-1 px-5 py-4 sm:flex-row sm:items-center sm:gap-6 sm:py-5">
      <span className="w-full shrink-0 font-mono text-xs uppercase tracking-[0.08em] text-marquee-amber sm:w-24">
        {row.day}
      </span>
      <span className="font-display text-lg font-bold text-seafoam md:text-xl">{row.act}</span>
    </div>
  );
}

