import { HeroSplit } from "@/components/HeroSplit";
import { PhotoFeatureRow } from "@/components/PhotoFeatureRow";
import { MarqueeBoard } from "@/components/MarqueeBoard";
import { ReviewStrip } from "@/components/ReviewStrip";
import { Reveal } from "@/components/Reveal";
import Link from "next/link";
import { ArrowRight } from "@phosphor-icons/react/dist/ssr";

// page-plans/home.md. Four distinct layout families across four content
// sections (HeroSplit, PhotoFeatureRow, MarqueeBoard teaser, ReviewStrip):
// passes the section-layout-repetition check comfortably.
export default function HomePage() {
  return (
    <>
      <HeroSplit
        headline="Pool, Darts, Shuffleboard, a Patio, and Live Bands on Weekends."
        subhead="Rated 4.3 stars by more than 500 regulars on Google. See tonight's lineup and get directions below."
        primaryCta={{ label: "See What's On Tonight", href: "/whats-on" }}
        secondaryCta={{ label: "Get Directions", href: "/visit#map" }}
        imageSrc="/images/hero-patio.jpg"
        imageAlt="Neighborhood bar patio at dusk with string bulb lighting and a pool table visible through the open doorway"
      />

      <PhotoFeatureRow
        headline="Pool Tables, Darts, Shuffleboard, and a Patio With Room to Spread Out."
        subhead="Walk in most nights and find an open table. On warm Gulf evenings, the patio fills up fast on weekends."
        imageSrc="/images/home-teaser.jpg"
        imageAlt="Bar interior opening onto a string-lit patio with a pool table visible"
        imageSide="left"
        link={{ label: "See the whole bar", href: "/the-bar" }}
      />

      <section>
        <Reveal className="mx-auto max-w-6xl px-4 pt-16 md:px-8 md:pt-24">
          <h2 className="text-balance font-display text-3xl font-bold tracking-[-0.01em] text-seafoam md:text-4xl">
            Live Bands Every Weekend, Right on the Patio.
          </h2>
          <p className="mt-4 max-w-[60ch] text-base text-seafoam/80 md:text-lg">
            Bands play the patio most weekend nights. Show up, grab a seat, and see who&apos;s
            on tonight.
          </p>
        </Reveal>
        <div className="mx-auto max-w-6xl px-4 pb-8 pt-8 md:px-8">
          <MarqueeBoard variant="teaser" />
          <Link
            href="/whats-on"
            className="mt-6 inline-flex items-center gap-1.5 font-body text-sm font-medium text-marquee-amber hover:underline"
          >
            See this weekend&apos;s lineup
            <ArrowRight size={16} weight="bold" />
          </Link>
        </div>
        <div className="pb-8 md:pb-16" />
      </section>

      <ReviewStrip />
    </>
  );
}

