import { ImageResponse } from "next/og";

// assets.md: social preview as a direct export of the marquee wordmark
// treatment (letter tiles on Bay Dusk), not a separate photo. System font
// only (no network font fetch) so this renders reliably in CI.
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

const WORDS = ["THE", "TEXAN", "DRIVE-IN"];

export default function OgImage() {
  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 24,
          background: "#0e3a3e",
        }}
      >
        <div style={{ display: "flex", gap: 16 }}>
          {WORDS.map((word) => (
            <div key={word} style={{ display: "flex" }}>
              {[...word].map((char, i) =>
                char === "-" ? (
                  <span
                    key={i}
                    style={{
                      color: "#e8a23c",
                      fontSize: 56,
                      fontWeight: 900,
                      padding: "0 4px",
                    }}
                  >
                    {char}
                  </span>
                ) : (
                  <span
                    key={i}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      width: 68,
                      height: 84,
                      color: "#e8a23c",
                      background: "#082226",
                      border: "2px solid rgba(232,162,60,0.35)",
                      fontSize: 44,
                      fontWeight: 900,
                    }}
                  >
                    {char}
                  </span>
                )
              )}
            </div>
          ))}
        </div>
        <span style={{ color: "#ecefe6", fontSize: 26, letterSpacing: 2 }}>
          Corpus Christi, Texas
        </span>
      </div>
    ),
    { ...size }
  );
}

