import Image from "next/image";
import Link from "next/link";
import { MarqueeWordmark } from "./MarqueeWordmark";
import { Button } from "./ui/button";

// page-plans/home.md section 2. Asymmetric split (DESIGN_VARIANCE 7): 55/45
// text/image on desktop, stacks to a single column on mobile with the image
// below the text. min-h-fit on mobile (never 100dvh) so the CTA is reachable
// without a forced full-screen scroll on a small phone in a parking lot.
export function HeroSplit({
  headline,
  subhead,
  primaryCta,
  secondaryCta,
  imageSrc,
  imageAlt,
}: {
  headline: string;
  subhead: string;
  primaryCta: { label: string; href: string };
  secondaryCta: { label: string; href: string };
  imageSrc: string;
  imageAlt: string;
}) {
  return (
    <section className="min-h-fit md:min-h-[calc(100dvh-72px)]">
      <div className="mx-auto grid max-w-6xl grid-cols-1 items-center gap-10 px-4 py-12 md:grid-cols-[55%_45%] md:gap-12 md:px-8 md:py-16">
        <div className="flex flex-col items-start gap-6">
          <MarqueeWordmark size="hero" />
          <h1 className="text-balance font-display text-4xl font-bold leading-[1.05] tracking-[-0.015em] text-seafoam md:text-6xl">
            {headline}
          </h1>
          <p className="max-w-[42ch] text-base text-seafoam/80 md:text-lg">{subhead}</p>
          <div className="flex flex-wrap gap-4">
            <Button asChild size="lg">
              <Link href={primaryCta.href}>{primaryCta.label}</Link>
            </Button>
            <Button asChild variant="outline" size="lg">
              <Link href={secondaryCta.href}>{secondaryCta.label}</Link>
            </Button>
          </div>
        </div>

        <div className="relative aspect-[4/3] w-full overflow-hidden">
          <Image
            src={imageSrc}
            alt={imageAlt}
            fill
            priority
            sizes="(min-width: 768px) 45vw, 100vw"
            className="object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-channel-ink/85 via-channel-ink/10 to-transparent" />
          <div className="absolute inset-0 bg-gradient-to-tr from-bay-dusk/50 via-transparent to-marquee-amber/20 mix-blend-color" />
        </div>
      </div>
    </section>
  );
}

