import { MapPin } from "@phosphor-icons/react/dist/ssr";
import { Button } from "./ui/button";
import { Reveal } from "./Reveal";
import { PHONE_DISPLAY, PHONE_TEL } from "@/lib/site";

const MAPS_DIRECTIONS_URL =
  "https://www.google.com/maps/search/?api=1&query=The+Texan+Drive-In+Corpus+Christi+TX";
// TODO: replace with the confirmed street address once the owner provides
// one (see brief.md's [STREET ADDRESS] placeholder). Until then this embeds
// a city-level view rather than guessing at a precise location.
const MAPS_EMBED_SRC = "https://www.google.com/maps?q=Corpus+Christi,+TX&output=embed";

// page-plans/visit.md section 2. Buoy Red is the one approved decorative,
// non-interactive use of that color (design-system.md), styled here as a
// small channel-marker pin badge over the embed rather than a generic
// teardrop, since Google's own in-iframe pin can't be restyled from outside.
export function MapEmbed() {
  return (
    <Reveal id="map" className="mx-auto max-w-5xl px-4 py-16 md:px-8 md:py-24">
      <div className="relative aspect-[4/3] w-full overflow-hidden border border-seafoam/15 md:aspect-video">
        <iframe
          title="Map centered on Corpus Christi, Texas"
          src={MAPS_EMBED_SRC}
          className="size-full border-0"
          loading="lazy"
          referrerPolicy="no-referrer-when-downgrade"
        />
        <div className="pointer-events-none absolute left-4 top-4 flex items-center gap-1.5 bg-channel-ink/90 px-3 py-1.5 font-mono text-xs uppercase tracking-[0.08em] text-seafoam">
          <MapPin size={16} weight="fill" className="text-buoy-red" />
          Corpus Christi, TX
        </div>
      </div>

      <div className="mt-6 flex flex-wrap gap-4">
        <Button asChild size="lg">
          <a href={MAPS_DIRECTIONS_URL} target="_blank" rel="noopener noreferrer">
            Open in Google Maps
          </a>
        </Button>
        <Button asChild variant="outline" size="lg">
          <a href={PHONE_TEL}>Call {PHONE_DISPLAY}</a>
        </Button>
      </div>
    </Reveal>
  );
}

