import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

/*
 * Restyled per design-system.md's corner-radius lock: buttons are the one
 * full-pill exception (rounded-full) to the site's sharp-corner panels, meant
 * to read like a marquee push-button light switch. Marquee Amber is the
 * site's one interactive accent (default variant); outline uses the Seafoam
 * Porcelain border per the hero's secondary CTA spec.
 */
const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-full border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:ring-3 focus-visible:ring-marquee-amber/50 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default:
          "bg-marquee-amber text-channel-ink hover:bg-marquee-amber/85",
        outline:
          "border-seafoam/70 bg-transparent text-seafoam hover:bg-seafoam/10 hover:border-seafoam",
        secondary: "bg-channel-ink text-seafoam hover:bg-channel-ink/80",
        ghost: "text-seafoam hover:bg-seafoam/10",
        destructive: "bg-buoy-red/15 text-buoy-red hover:bg-buoy-red/25",
        link: "text-marquee-amber underline-offset-4 hover:underline",
      },
      size: {
        default: "h-11 gap-2 px-6",
        sm: "h-9 gap-1.5 px-4 text-[0.8rem]",
        lg: "h-12 gap-2 px-8 text-base",
        icon: "size-11",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

