import Image from "next/image";
import { Reveal } from "./Reveal";

type AssetItem = {
  src: string;
  alt: string;
  caption: string;
};

// Bento-style grid for exactly three items (pool, darts, shuffleboard):
// one large cell + two stacked smaller cells, not three equal boxes
// (page-plans/the-bar.md). Collapses to a single column below md.
export function AssetGrid({ items }: { items: [AssetItem, AssetItem, AssetItem] }) {
  const [large, a, b] = items;
  return (
    <Reveal className="mx-auto max-w-6xl px-4 py-16 md:px-8 md:py-24">
      <div className="grid grid-cols-1 gap-4 md:grid-cols-[2fr_1fr] md:grid-rows-2">
        <AssetCell item={large} className="md:row-span-2" />
        <AssetCell item={a} />
        <AssetCell item={b} />
      </div>
    </Reveal>
  );
}

function AssetCell({ item, className = "" }: { item: AssetItem; className?: string }) {
  // aspect-[4/3] applies at every breakpoint (not just mobile): with the 2fr/1fr
  // column split above, a proportional aspect ratio makes the two stacked
  // small cells add up to exactly the large cell's height on desktop too.
  // An earlier md:aspect-auto override left `fill` images with a 0-height
  // parent on desktop (Next.js image warning, cells invisible); don't reintroduce it.
  return (
    <figure className={`relative aspect-[4/3] w-full overflow-hidden ${className}`}>
      <Image
        src={item.src}
        alt={item.alt}
        fill
        sizes="(min-width: 768px) 50vw, 100vw"
        className="object-cover"
      />
      <figcaption className="absolute bottom-0 left-0 bg-channel-ink/80 px-3 py-1.5 font-mono text-xs uppercase tracking-[0.08em] text-seafoam">
        {item.caption}
      </figcaption>
    </figure>
  );
}

