import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "@phosphor-icons/react/dist/ssr";
import { Reveal } from "./Reveal";

// One image + text split section. Used at most twice in a row anywhere on
// the site (zigzag-alternation cap, design-taste-frontend section 4.7).
export function PhotoFeatureRow({
  headline,
  subhead,
  imageSrc,
  imageAlt,
  imageSide = "left",
  link,
}: {
  headline: string;
  subhead: string;
  imageSrc: string;
  imageAlt: string;
  imageSide?: "left" | "right";
  link?: { label: string; href: string };
}) {
  return (
    <Reveal className="mx-auto max-w-6xl px-4 py-16 md:px-8 md:py-24">
      <div
        className={`grid grid-cols-1 items-center gap-8 md:grid-cols-2 md:gap-16 ${
          imageSide === "right" ? "md:[&>*:first-child]:order-2" : ""
        }`}
      >
        <div className="relative aspect-[4/3] w-full overflow-hidden">
          <Image
            src={imageSrc}
            alt={imageAlt}
            fill
            sizes="(min-width: 768px) 50vw, 100vw"
            className="object-cover"
          />
        </div>
        <div className="flex flex-col items-start gap-4">
          <h2 className="text-balance font-display text-3xl font-bold tracking-[-0.01em] text-seafoam md:text-4xl">
            {headline}
          </h2>
          <p className="max-w-[60ch] text-base text-seafoam/80 md:text-lg">{subhead}</p>
          {link && (
            <Link
              href={link.href}
              className="inline-flex items-center gap-1.5 font-body text-sm font-medium text-marquee-amber hover:underline"
            >
              {link.label}
              <ArrowRight size={16} weight="bold" />
            </Link>
          )}
        </div>
      </div>
    </Reveal>
  );
}

