import type { Metadata } from "next";
import { PageIntro } from "@/components/PageIntro";
import { MarqueeBoard } from "@/components/MarqueeBoard";
import { PhotoFeatureRow } from "@/components/PhotoFeatureRow";
import { Reveal } from "@/components/Reveal";
import { Button } from "@/components/ui/button";
import Link from "next/link";

export const metadata: Metadata = {
  title: "What's On",
  description: "Bands play most weekend nights. Show up and grab a seat.",
};

// page-plans/whats-on.md. No claim about tickets, cover charge, or price
// anywhere on this page; neither is verified.
export default function WhatsOnPage() {
  return (
    <>
      <PageIntro
        headline="This Weekend on the Patio."
        subhead="Bands play most weekend nights. Show up and grab a seat."
      />

      <div className="pt-8 md:pt-12">
        <MarqueeBoard variant="full" />
      </div>

      <PhotoFeatureRow
        headline="A Full Patio, a Band, No Fuss."
        subhead="It's a neighborhood patio with a band on it, not a concert hall."
        imageSrc="/images/band-night.jpg"
        imageAlt="Silhouette of a small band playing on a string-lit outdoor patio stage at night"
        imageSide="left"
      />

      <Reveal className="mx-auto max-w-6xl px-4 pb-16 text-center md:px-8 md:pb-24">
        <p className="text-base text-seafoam/80 md:text-lg">
          Already decided? Find directions below.
        </p>
        <Button render={<Link href="/visit#map" />} size="lg" className="mt-6">
