import type { Metadata, Viewport } from "next";
import { Archivo, IBM_Plex_Mono, Roboto_Slab } from "next/font/google";
import "./globals.css";
import { NavBar } from "@/components/NavBar";
import { Footer } from "@/components/Footer";
import { FACEBOOK_URL, RATING_VALUE, REVIEW_COUNT, YELP_URL } from "@/lib/site";

const robotoSlab = Roboto_Slab({
  subsets: ["latin"],
  weight: ["700", "900"],
  variable: "--font-roboto-slab",
  display: "swap",
});

const archivo = Archivo({
  subsets: ["latin"],
  weight: ["400", "500"],
  variable: "--font-archivo",
  display: "swap",
});

const plexMono = IBM_Plex_Mono({
  subsets: ["latin"],
  weight: ["400", "500"],
  variable: "--font-plex-mono",
  display: "swap",
});

export const metadata: Metadata = {
  title: {
    default: "The Texan Drive-In | Corpus Christi Neighborhood Bar",
    template: "%s | The Texan Drive-In",
  },
  description:
    "Pool, darts, shuffleboard, a patio, and live bands on weekends. Rated 4.3 stars by more than 500 regulars on Google. Concept site, pending business owner review.",
  openGraph: {
    title: "The Texan Drive-In | Corpus Christi Neighborhood Bar",
    description:
      "Pool, darts, shuffleboard, a patio, and live bands on weekends in Corpus Christi, Texas.",
    locale: "en_US",
    type: "website",
  },
};

export const viewport: Viewport = {
  colorScheme: "dark",
  themeColor: "#0e3a3e",
};

// Non-negotiable rule zero (implementation.md): no invented contact data in
// structured data. telephone is real and confirmed (brief.md); address and
// email are omitted entirely rather than filled with a bracket placeholder,
// since a search engine would parse "[STREET ADDRESS]" as real garbage data.
const jsonLd = {
  "@context": "https://schema.org",
  "@type": "BarOrPub",
  name: "The Texan Drive-In",
  telephone: "+13614445522",
  addressLocality: "Corpus Christi",
  addressRegion: "TX",
  addressCountry: "US",
  aggregateRating: {
    "@type": "AggregateRating",
    ratingValue: RATING_VALUE,
    reviewCount: REVIEW_COUNT,
  },
  sameAs: [FACEBOOK_URL, YELP_URL],
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${robotoSlab.variable} ${archivo.variable} ${plexMono.variable}`}>
      <body className="flex min-h-dvh flex-col">
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
        />
        <NavBar />
        <main className="flex-1">{children}</main>
        <Footer />
      </body>
    </html>
  );
}

